import 'dart:async';
import 'dart:convert';
import 'dart:math' as math;

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

void main() {
  runApp(const CodiceApp());
}

class CodiceApp extends StatelessWidget {
  const CodiceApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      title: 'Códice',
      theme: ThemeData(
        brightness: Brightness.dark,
        fontFamily: 'Arial',
        useMaterial3: true,
        colorScheme: ColorScheme.fromSeed(
          seedColor: kPurple,
          brightness: Brightness.dark,
        ),
      ),
      // A moldura embrulha o Navigator inteiro: assim a troca de tela,
      // os AlertDialogs, as SnackBars e o bottom sheet acontecem DENTRO
      // do "celular", em vez de escaparem para a janela toda.
      builder: (context, child) => PhoneFrame(child: child!),
      home: const WelcomeScreen(),
    );
  }
}

