// ============================================================
// APP SHELL — NAVEGAÇÃO PRINCIPAL
// ============================================================

class AppShell extends StatefulWidget {
  final int abaInicial;

  const AppShell({super.key, this.abaInicial = 0});

  @override
  State<AppShell> createState() => _AppShellState();
}

class _AppShellState extends State<AppShell> {
  late int selectedIndex = widget.abaInicial;

  final List<Widget> pages = const [
    HomeScreen(),
    ConversationScreen(),
    DiaryScreen(),
    CityScreen(),
    MeetingsScreen(),
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: kBg,
      body: SafeArea(
        bottom: false,
        child: IndexedStack(
          index: selectedIndex,
          children: pages,
        ),
      ),
      // No slot próprio do Scaffold, as SnackBars flutuam ACIMA da barra
      // em vez de cobrirem a navegação.
      bottomNavigationBar: SafeArea(
        top: false,
        child: BottomNavigation(
          selectedIndex: selectedIndex,
          onSelected: (index) {
            // Trocar de aba some com o aviso da aba anterior.
            ScaffoldMessenger.of(context).hideCurrentSnackBar();
            setState(() => selectedIndex = index);
          },
        ),
      ),
    );
  }
}

