// BARRA INFERIOR
// ============================================================

class BottomNavigation extends StatelessWidget {
  final int selectedIndex;
  final ValueChanged<int> onSelected;

  const BottomNavigation({
    super.key,
    required this.selectedIndex,
    required this.onSelected,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      height: 68,
      decoration: const BoxDecoration(
        color: kBottom,
        border: Border(
          top: BorderSide(
            color: kLine,
            width: 1,
          ),
        ),
      ),
      child: Row(
        children: [
          bottomItem(0, Icons.sentiment_satisfied_alt_outlined, 'Navi'),
          bottomItem(1, Icons.chat_bubble_outline, 'Conversa'),
          bottomItem(2, Icons.article_outlined, 'Diário'),
          bottomItem(3, Icons.account_balance_outlined, 'Cidade'),
          bottomItem(4, Icons.people_outline, 'Encontros'),
        ],
      ),
    );
  }

  Widget bottomItem(int index, IconData icon, String label) {
    final selected = selectedIndex == index;

    return Expanded(
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: () => onSelected(index),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Container(
              width: 27,
              height: 23,
              decoration: selected
                  ? BoxDecoration(
                      color: const Color(0xFF251B4B),
                      borderRadius: BorderRadius.circular(12),
                    )
                  : null,
              child: Icon(
                icon,
                size: 17,
                color: selected ? kPurple : const Color(0xFF8C8798),
              ),
            ),
            const SizedBox(height: 4),
            Text(
              label,
              style: TextStyle(
                color: selected ? kPurple : const Color(0xFF898494),
                fontSize: 9,
                fontWeight:
                    selected ? FontWeight.bold : FontWeight.normal,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// ============================================================
// CÍRCULOS DO CHÃO
// ============================================================

/// Qual metade dos anéis desenhar. A de trás fica atrás da Frost e a da
/// frente passa na frente dela: é isso que dá a sensação de chão.
enum MetadeDoChao { tras, frente }

class GroundCirclesPainter extends CustomPainter {
  final MetadeDoChao metade;

  const GroundCirclesPainter({required this.metade});

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = const Color(0xFF6CEFF1)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 0.9;

    final centro = Offset(size.width / 2, size.height / 2);

    // Arco de cima (π → 2π) é o fundo; o de baixo (0 → π) é a frente.
    final inicio = metade == MetadeDoChao.tras ? math.pi : 0.0;

    // Largura em fração do palco, altura fixa: anéis concêntricos.
    const aneis = [(0.74, 26.0), (0.54, 19.0), (0.34, 12.0)];
    for (final (largura, altura) in aneis) {
      canvas.drawArc(
        Rect.fromCenter(
          center: centro,
          width: size.width * largura,
          height: altura,
        ),
        inicio,
        math.pi,
        false,
        paint,
      );
    }
  }

  @override
  bool shouldRepaint(covariant GroundCirclesPainter oldDelegate) =>
      oldDelegate.metade != metade;
}
